<script setup lang="ts">
import { ArrowLeft, ArrowRight, ArrowUp, ArrowUpRight } from '@lucide/vue'
import { computed, ref } from 'vue'
import { RouterLink, useRoute, useRouter } from 'vue-router'
import EvidenceList from '../components/evidence/EvidenceList.vue'
import SourceDrawer from '../components/evidence/SourceDrawer.vue'
import StatusBadge from '../components/common/StatusBadge.vue'
import ServiceBadge from '../components/common/ServiceBadge.vue'
import SpatialDetailMap from '../components/map/SpatialDetailMap.vue'
import { useDataStore } from '../stores/data'
import type { SourceRecord } from '../types/data'
import { coordinateSemanticsLabel, dateLabel, geometryNoteLabel, locationLabel, locationMethodLabel, profileReviewLabel, verificationLabel, yesNoLabel } from '../services/labels'
const route = useRoute(); const router = useRouter(); const data = useDataStore(); const source = ref<SourceRecord | null>(null)
const site = computed(() => data.sites.find(item => item.properties.site_id === route.params.siteId))
const profile = computed(() => data.profiles.find(item => item.site_id === route.params.siteId))
const evidence = computed(() => data.evidenceRows.filter(row => row.entity_id === site.value?.properties.site_id))
const locatedCount = computed(() => profile.value?.components.filter(component => component.location).length ?? 0)
const selectedAnchor = computed({ get: () => typeof route.query.component === 'string' ? route.query.component : 'main', set: id => { void router.replace({ query: { ...route.query, component: id === 'main' ? undefined : id } }) } })
const chapterRoute = (hash: string) => ({ path: route.path, query: route.query, hash })
function locate(id: string) { void router.push({ path: route.path, query: { ...route.query, component: id }, hash: '#spatial-map' }) }
function openSource(id: string) { source.value = data.sourceRegistry?.sources[id] ?? null }
</script>
<template>
  <div v-if="site && profile" class="page detail-page"><div class="detail-actions"><RouterLink class="back-link" :to="{ path: '/sites', query: route.query }"><ArrowLeft :size="15" aria-hidden="true" /> 返回参考站点</RouterLink><div class="detail-links"><RouterLink class="back-link" :to="{ path: '/map', query: { ...route.query, site: profile.site_id, component: undefined } }">在地图中查看</RouterLink><RouterLink class="back-link" :to="{ path: '/model', query: { site: profile.site_id } }">查看实体模型 <ArrowRight :size="15" aria-hidden="true" /></RouterLink></div></div>
  <header class="detail-head"><div><span class="eyebrow cyan">CRS记录 {{ String(profile.source_record_no).padStart(2,'0') }}</span><h2>{{ site.properties.display_name }}</h2><div class="detail-meta"><span>{{ locationLabel(site.properties.location_label) }}</span><ServiceBadge :value="site.properties.service_component" /><StatusBadge :value="site.properties.coordinate_semantics" /></div></div><div class="detail-review"><strong>{{ profileReviewLabel(profile.review_status) }}</strong><small v-if="profile.review_record">{{ profile.review_record.reviewer }} · AI代理 · {{ dateLabel(profile.review_record.reviewed_at) }}</small></div></header>
  <p class="detail-lead">{{ profile.description_short }}</p><div class="detail-kpis"><div><span>公开参考位置</span><strong>{{ Number(site.properties.latitude).toFixed(site.properties.coordinate_semantics === 'LOCALITY_ANCHOR' ? 2 : 5) }}°, {{ Number(site.properties.longitude).toFixed(site.properties.coordinate_semantics === 'LOCALITY_ANCHOR' ? 2 : 5) }}°</strong><small>{{ coordinateSemanticsLabel(site.properties.coordinate_semantics) }}</small></div><div><span>组成与关联</span><strong>{{ profile.components.length }} <small>条关系</small> · {{ locatedCount }} <small>处独立定位</small></strong><small>地理地点与文字关系分别表达</small></div><div><span>字段证据</span><strong>{{ evidence.length }} <small>条可追溯记录</small></strong><small>字段值、来源与原始记录定位</small></div></div>
  <nav class="detail-sections" aria-label="详情章节"><RouterLink :to="chapterRoute('#spatial-map')">空间地图</RouterLink><RouterLink :to="chapterRoute('#profile-text')">详细画像</RouterLink><RouterLink v-if="profile.components.length" :to="chapterRoute('#facility-relations')">关联设施</RouterLink><RouterLink :to="chapterRoute('#field-evidence')">字段证据</RouterLink></nav>
  <section id="spatial-map" class="panel detail-map"><SpatialDetailMap v-model:selected-id="selectedAnchor" :profile="profile" :site="site" @source="openSource" /></section>
  <section id="profile-text" class="panel profile-card" aria-label="站点画像"><div class="panel-heading"><div><h3>详细画像</h3><small>保留完整公开事实与逐节来源</small></div><span class="tag derived">{{ profileReviewLabel(profile.review_status) }}</span></div><nav class="profile-chapters" aria-label="画像章节"><RouterLink v-for="(section,index) in profile.description_sections" :key="section.title" :to="chapterRoute('#profile-chapter-'+index)">{{ section.title }}</RouterLink></nav><section v-for="(section,index) in profile.description_sections" :id="'profile-chapter-'+index" :key="section.title" class="profile-section"><h3>{{ section.title }}</h3><p>{{ section.text }}</p><div class="profile-sources"><button v-for="id in section.source_ids" :key="id" type="button" class="source-link" @click="openSource(id)">来源 · {{ data.sourceRegistry?.sources[id]?.title ?? id }} <ArrowUpRight :size="14" aria-hidden="true" /></button></div></section></section>
  <section v-if="profile.components.length" id="facility-relations" class="panel" aria-label="关联设施与组织"><div class="panel-heading"><div><h3>关联设施与组织</h3><small>{{ profile.components.length }} 条具名关系 · {{ locatedCount }} 处可独立定位</small></div></div><div class="relation-cards"><article v-for="component in profile.components" :key="component.component_id" :class="{ selected: selectedAnchor === component.component_id }"><div class="relation-title"><strong>{{ component.name }}</strong><span class="tag" :class="component.location ? 'derived' : 'source'">{{ component.location ? '独立地点' : '文字关系' }}</span></div><p>{{ component.relationship }}</p><div class="relation-actions"><button v-if="component.location" type="button" class="secondary-btn" @click="locate(component.component_id)">定位到地图 <ArrowUp :size="14" aria-hidden="true" /></button><span v-else class="muted">该关系保留文字说明</span><button v-for="id in component.source_ids" :key="id" type="button" class="source-link" @click="openSource(id)">查看关系出处 <ArrowUpRight :size="14" aria-hidden="true" /></button></div></article></div></section>
  <details class="panel profile-provenance"><summary>原始目录、定位依据与审核记录</summary><div class="provenance-grid"><section><h3>CRS原始参考</h3><dl class="facts"><dt>原始名称</dt><dd>{{ site.properties.source_name }}</dd><dt>地区</dt><dd>{{ locationLabel(site.properties.location_label) }}</dd><dt>机构</dt><dd><ServiceBadge :value="site.properties.service_component" /></dd><dt>DoD运营</dt><dd>{{ yesNoLabel(site.properties.dod_operated_raw) }}</dd><dt>来源页码</dt><dd>{{ site.properties.source_page }}</dd></dl></section><section><h3>选点依据</h3><strong>{{ profile.location_evidence.anchor_name }}</strong><p class="muted">{{ locationMethodLabel(profile.location_evidence.method) }} · {{ profile.location_evidence.source_record_id }}</p><p>{{ profile.location_evidence.selection_reason }}</p><p class="warning-copy">{{ geometryNoteLabel(site.properties.geometry_note) }}</p><button type="button" class="secondary-btn" @click="openSource(profile.location_evidence.source_id)">查看定位来源</button></section></div><section v-if="profile.review_record" aria-label="来源审核记录"><h3>来源审核记录</h3><p>审核员：{{ profile.review_record.reviewer }}（AI代理） · {{ dateLabel(profile.review_record.reviewed_at) }}</p><p>已核对归档CRS原字段、公开画像事实、定位来源与关联设施；结论适用于各记录注明的对象与范围。</p><ul><li v-for="finding in profile.review_record.findings" :key="finding">{{ finding }}</li></ul><code>{{ profile.review_record.input_sha256 }}</code></section><h3>画像来源与定位</h3><div class="profile-sources"><button v-for="id in profile.profile_source_ids" :key="id" type="button" class="source-link" @click="openSource(id)">{{ data.sourceRegistry?.sources[id]?.title ?? id }} <ArrowUpRight :size="14" aria-hidden="true" /></button></div><ul class="document-list"><li v-for="document in profile.evidence_documents" :key="document.source_id"><strong>{{ data.sourceRegistry?.sources[document.source_id]?.title }}</strong><p>{{ document.section }} · {{ document.date_note }}</p><span class="tag derived">{{ verificationLabel(document.verification_status) }}</span></li></ul></details>
  <section class="scope-note" aria-label="资料适用范围"><h3>资料适用范围</h3><ul><li v-for="item in profile.unknown_items" :key="item">{{ item }}</li></ul></section>
  <section id="field-evidence" class="panel" aria-label="字段证据"><div class="panel-heading"><div><h3>字段证据</h3><small>{{ evidence.length }} 条关联记录，全部可查</small></div></div><EvidenceList :rows="evidence" @source="openSource" /></section><SourceDrawer :source="source" @close="source = null" /></div>
  <section v-else class="page panel" aria-label="站点未找到"><h2>未找到参考站点</h2><p class="muted">当前目录没有这个站点编号，请返回目录选择站点。</p><RouterLink class="back-link" to="/sites"><ArrowLeft :size="15" aria-hidden="true" /> 返回参考站点</RouterLink></section>
</template>
<style scoped>
