w-wrap:anywhere;line-height:1.6}.source-link:hover{background:#e2f1ec}.relation-cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}.relation-cards article{padding:18px;border:1px solid var(--line);border-radius:9px;background:#f7fafb;min-width:0}.relation-cards article.selected{border-color:var(--cyan);background:#edf8f4}.relation-title{display:flex;align-items:start;justify-content:space-between;gap:12px;flex-wrap:wrap}.relation-title strong{font-size:15px;overflow-wrap:anywhere}.relation-cards p{font-size:14px;line-height:1.8;overflow-wrap:anywhere}.relation-actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.relation-actions .secondary-btn,.relation-actions .muted{font-size:12px}.profile-provenance summary{font-size:16px;font-weight:600}.provenance-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin:25px 0}.provenance-grid h3,.profile-provenance h3{font-size:17px;margin:20px 0 14px}.profile-provenance p,.profile-provenance li{font-size:14px;line-height:1.8;overflow-wrap:anywhere}.profile-provenance code{display:block;font-size:12px;overflow-wrap:anywhere}.document-list{list-style:none;padding:0;display:grid;gap:16px;margin-top:20px}.document-list li{border-top:1px solid var(--line);padding-top:15px}.scope-note{padding:18px 22px;background:#eef4f5;border-left:3px solid #799ba7;border-radius:0 9px 9px 0}.scope-note h3{font-size:15px;margin:0}.scope-note ul{margin:12px 0 0;padding-left:19px;color:var(--muted);font-size:13px;line-height:1.8}.detail-map,#field-evidence,#facility-relations,#profile-text{scroll-margin-top:96px}
.detail-links{display:flex;gap:22px;flex-wrap:wrap}
